async function main() {
  const category = await prisma.category.upsert({
    where: { slug: "system-design" },
    update: { name: "System Design" },
    create: {
      group: "Technology", name: "System Design", slug: "system-design" },
  });

  const subcategoryIds: Record<string, string> = {};

  for (const sub of subcategories) {
    const row = await prisma.subcategory.upsert({
      where: { categoryId_slug: { categoryId: category.id, slug: sub.slug } },
      update: { name: sub.name, categoryId: category.id },
      create: { name: sub.name, slug: sub.slug, categoryId: category.id },
    });
    subcategoryIds[sub.slug] = row.id;
  }

  for (const item of questions) {
    const subcategoryId = subcategoryIds[item.subcategorySlug];

    await prisma.interviewQuestion.upsert({
      where: { slug: item.slug },
      update: {
        question: item.question,
        categoryId: category.id,
        subcategoryId,
        experienceLevel: ExperienceLevel.MID_LEVEL,
        difficulty: Difficulty.MEDIUM,
        interviewType: InterviewType.TECHNICAL,
        shortDescription: item.shortDescription,
        explanation: item.explanation,
        sampleAnswer: item.sampleAnswer,
        detailedAnswer: item.detailedAnswer,
        keyPoints: item.keyPoints,
        commonMistakes: item.commonMistakes,
        followUpQuestions: item.followUpQuestions,
        tags: item.tags,
        isPublished: true,
      },
      create: {
        question: item.question,
        slug: item.slug,
        categoryId: category.id,
        subcategoryId,
        experienceLevel: ExperienceLevel.MID_LEVEL,
        difficulty: Difficulty.MEDIUM,
        interviewType: InterviewType.TECHNICAL,
        shortDescription: item.shortDescription,
        explanation: item.explanation,
        sampleAnswer: item.sampleAnswer,
        detailedAnswer: item.detailedAnswer,
        keyPoints: item.keyPoints,
        commonMistakes: item.commonMistakes,
        followUpQuestions: item.followUpQuestions,
        tags: item.tags,
        isPublished: true,
      },
    });
  }

  console.log(`System Design interview seed completed successfully. {questions.length} questions seeded.`);
}

main()
  .catch((error) => {
    console.error("System Design interview seed failed:", error);
    process.exit(1);
  })
  .finally(async () => {
    await prisma.$disconnect();
  });
